public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    }
    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] temp = new int[nums.length-1];
        for (int j = 0; j < nums.length-1; j++) {
            if (j == i) {
                temp[j] = nums[j+1];
            } else {
                temp[j] = nums[j];
            }
        }
        List<List<Integer>> subResult = permute(temp);
        for (List<Integer> list : subResult) {
            list.add(0, nums[i]);
            result.add(list);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
      result.add(Arrays.asList(nums));
    } else {
      for (int i = 0; i < nums.length; i++) {
        int[] remaining = Arrays.copyOfRange(nums, 0, i)
            .concat(Arrays.copyOfRange(nums, i + 1, nums.length));
        for (List<Integer> perm : permute(remaining)) {
          perm.add(0, nums[i]);
          result.add(perm);
        }
      }
    }
    return result;
  }

