public static int maxRegions(int N) {
    // Initialize the list of regions
    ArrayList<Integer> listOfRegions = new ArrayList<>();
    listOfRegions.add(1);

    // Count the number of regions for each triangle
    for (int i = 1; i <= N; i++) {
      // Get the current number of regions
      int numRegions = listOfRegions.size();

      // Add new regions to the list
      for (int j = 0; j < numRegions; j++) {
        listOfRegions.add(listOfRegions.get(j) * 2);
      }
    }

    // Return the maximum number of regions
    return listOfRegions.size();
  }

