String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Check if the starting and ending coordinates are within the n-teresting space
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // Create a set to store the visited n-tersections
  Set<String> visited = new HashSet<>();

  // Create a queue to store the n-tersections to be visited
  Queue<int[]> toVisit = new LinkedList<>();

  // Add the starting n-tersection to the queue
  toVisit.offer(start);

  // Iterate through the paths
  while (!toVisit.isEmpty()) {
    // Get the current n-intersection and its neighbors
    int[] current = toVisit.poll();
    int[][] neighbors = paths[current[0]][current[1]];

    // Check if the ending n-intersection has been reached
    if (neighbors[0] == end[0] && neighbors[1] == end[1]) {
      return "can be travelled";
    }

    // Add the neighbors to the queue and the visited set
    for (int i = 0; i < neighbors.length; i++) {
      String neighbor = neighbors[i];
      if (!visited.contains(neighbor)) {
        visited.add(neighbor);
        toVisit.offer(neighbors);
      }
    }
  }

  // If all n-intersections have been visited and the ending n-intersection has not been reached, return "cannot be travelled"
  return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending points are in the n-interesting space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Initialize a queue to store the starting point and mark it as visited
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    Set<Integer> visited = new HashSet<>();
    visited.add(start[0] * n + start[1]);

    // Breadth-first search to check if the ending point can be reached from the starting point
    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        // Add the current point's neighbors to the queue if they haven't been visited yet
        for (int[] path : paths) {
            int x = current[0] + path[0];
            int y = current[1] + path[1];
            if (x >= 0 && x < n && y >= 0 && y < n && visited.add(x * n + y)) {
                queue.add(new int[] {x, y});
            }
        }
    }

    // If the ending point was not found, return "cannot be travelled"
    return "cannot be travelled";
}

