public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Check if the starting n-tersection is valid
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
    return "cannot be travelled";
  }

  // Check if the ending n-tersection is valid
  if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // Check if the starting and ending n-tersections are the same
  if (start.equals(end)) {
    return "can be travelled";
  }

  // Initialize a set to store the visited n-tersections
  Set<String> visited = new HashSet<>();

  // Initialize a queue to store the n-tersections to be visited
  Queue<String> toVisit = new LinkedList<>();

  // Add the starting n-tersection to the queue
  toVisit.add(start[0] + "," + start[1]);

  // Loop until the ending n-tersection is found or the queue is empty
  while (!toVisit.isEmpty()) {
    // Get the current n-tersection from the queue
    String current = toVisit.remove();

    // Check if the current n-tersection is the ending n-tersection
    if (current.equals(end[0] + "," + end[1])) {
      return "can be travelled";
    }

    // Add the current n-tersection to the visited set
    visited.add(current);

    // Get the neighbors of the current n-tersection
    int[][] neighbors = paths[Integer.parseInt(current.split(",")[0])][Integer.parseInt(current.split(",")[1])];

    // Loop through the neighbors
    for (int[] neighbor : neighbors) {
      // Check if the neighbor is not in the visited set and is not out of bounds
      if (neighbor[0] >= 0 && neighbor[0] < n && neighbor[1] >= 0 && neighbor[1] < n && !visited.contains(neighbor[0] + "," + neighbor[1])) {
        // Add the neighbor to the queue
        String neighborString = neighbor[0] + "," + neighbor[1];
        visited.add(neighborString);
        toVisit.add(neighborString);
      }
    }
  }

  // If the queue is empty, return "cannot be travelled"
  return "cannot be travelled";
}

