public static String appx(String word1, String word2) {
        // Create a hashmap to store the common letters
        Map<String, Integer> commonLetters = new HashMap<>();

        // Count the number of common letters
        int numCommonLetters = 0;
        for (int i = 0; i < word1.length(); i++) {
            char letter1 = word1.charAt(i);
            for (int j = 0; j < word2.length(); j++) {
                char letter2 = word2.charAt(j);
                if (letter1 == letter2) {
                    commonLetters.put(letter1, commonLetters.getOrDefault(letter1, 0) + 1);
                    numCommonLetters++;
                    break;
                }
            }
        }

        // Divide the number of common letters by the sum of the lengths of the two words
        // to get the approximate value as a reduced fraction
        int denom = word1.length() + word2.length();
        int numer = numCommonLetters;
        String approxVal = "";
        if (denom != 0) {
            approxVal = Integer.toString(numer) + "/" + Integer.toString(denom);
        } else {
            approxVal = "0";
        }

        // Output the approximate value as a reduced fraction
        return "appx(" + word1 + ", " + word2 + ") = " + approxVal;
    }

