public static String convertDatesToWeekdays(String date) {
    // Split the input date string into day, month, and year using the whitespace as a delimiter
    String[] dateComponents = date.split(" ");

    // Use the SimpleDateFormat class to parse the date string into a Date object
    Date parsedDate = new SimpleDateFormat("MM dd yyyy").parse(dateComponents[0] + " " + dateComponents[1] + " " + dateComponents[2]);

    // Use the Calendar class to get the day of the week from the Date object
    Calendar calendar = Calendar.getInstance();
    calendar.setTime(parsedDate);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);

    // Use the SimpleDateFormat class to format the Date object into a string in the format "MMMM dd, yyyy"
    String formattedDate = new SimpleDateFormat("MMMM dd, yyyy").format(parsedDate);

    // Return a string with the formatted date and the appropriate day of the week
    return formattedDate + " is a " + getDayOfWeekString(dayOfWeek);
}

public static String convertDatesToWeekdays(String date) {
