        cal.setTime(parsedDate);
        int weekday = cal.get(Calendar.DAY_OF_WEEK);

        // Use a switch statement to map the weekday to its corresponding name
        String weekdayName;
        switch (weekday) {
            case Calendar.SUNDAY:
