public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest 5% of elements
    int smallest = (int) (arr.length * 0.05);
    for (int i = 0; i < smallest; i++) {
        arr[i] = 0;
    }

    // Remove the largest 5% of elements
    int largest = (int) (arr.length * 0.05);
    for (int i = arr.length - 1; i >= largest; i--) {
        arr[i] = 0;
    }

    // Calculate the mean
    double sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }
    return sum / (arr.length - smallest - largest);
}

public static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Calculate the index of the smallest and largest 5% of elements
    int minIndex = (int)Math.round(arr.length * 0.05);
    int maxIndex = arr.length - (int)Math.round(arr.length * 0.05);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = minIndex; i < maxIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    double mean = (double)sum / (arr.length - 2 * minIndex);

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
}

public static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the smallest 5% index
    int minIndex = (int) (arr.length * 0.05);

    // Find the largest 5% index
    int maxIndex = (int) (arr.length - 1 - (arr.length * 0.05));

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int i = minIndex; i <= maxIndex; i++) {
        sum += arr[i];
    }

    // Calculate the mean
    double mean = (double) sum / (maxIndex - minIndex + 1);

    // Round the result to 5 decimal places
    return Math.round(mean * 100000) / 100000;
}

public double trimMean(int[] arr) {
  // Remove the smallest 5% of the elements
  int size = arr.length - (int) (arr.length * 0.05);
  int[] temp = Arrays.copyOf(arr, size);
  Arrays.sort(temp);
  int remove = (int) (size * 0.05);
  temp = Arrays.copyOf(temp, temp.length - remove);

  // Remove the largest 5% of the elements
  size = temp.length - (int) (temp.length * 0.05);
  temp = Arrays.copyOf(temp, size);
  Arrays.sort(temp);
  remove = (int) (temp.length * 0.05);
  temp = temp.length - remove;

  // Calculate the remaining mean
  double mean = 0.0;
  for (int i = 0; i < temp.length; i++) {
    mean += temp[i];
  }
  mean /= temp.length;

  // Return the mean with an error within 10^-5
  return mean;
}

private static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the smallest 5% of elements
    int smallestFivePercent = (int) (arr.length * 0.05);
    int smallestFivePercentIndex = (int) (arr.length - smallestFivePercent);

    // Find the largest 5% of elements
    int largestFivePercent = (int) (arr.length * 0.05);
    int largestFivePercentIndex = (int) (arr.length - largestFivePercent);

    // Calculate the mean
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        if (i >= smallestFivePercentIndex && i <= largestFivePercentIndex) {
            mean += arr[i];
        }
    }
    mean /= arr.length - 2 * smallestFivePercent;

    return mean;
}

public boolean canArrange(int[] arr, int k) {
  Set<Integer> set = new HashSet<>();
  for (int num : arr) {
    if (num % k == 0) {
      set.add(num / k);
    } else {
      set.add((num / k) + 1);
    }
  }

  return set.size() <= arr.length / 2;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0 || k <= 1) {
        return false;
    }
    Map<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < n; i++) {
        map.put(arr[i], map.getOrDefault(arr[i], 0) + 1);
    }
    for (int i = 0; i < n; i++) {
        int key = arr[i];
        if (map.get(key) == 1) {
            map.remove(key);
        } else {
            map.put(key, map.get(key) - 1);
        }
        if (map.size() == n / 2) {
            for (int count : map.values()) {
                if (count % k != 0) {
                    return false;
                }
            }
            return true;
        }
    }
    return false;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1 || n == 0) {
        return false;
    }
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        counts[arr[i] % k]++;
    }
    int pairs = 0;
    for (int i = 0; i < counts.length; i++) {
        if (counts[i] > 0) {
            pairs += counts[i] / 2;
            if (counts[i] % 2 == 1 && counts[i] > 1) {
                pairs++;
            }
        }
    }
    return pairs == n / 2;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to keep track of the counts of each number
    Map<Integer, Integer> counts = new HashMap<>();
    for (int i : arr) {
        counts.put(i, counts.getOrDefault(i, 0) + 1);
    }

    // Iterate over the counts and find the pairs that sum up to k
    for (int num : counts.keySet()) {
        int rem = k - num;
        if (rem == num) {
            // If the number is its own remainder, then it can be paired with itself
            if (counts.get(num) > 1) {
                return true;
            }
        } else if (counts.containsKey(rem)) {
            // If there is another number that can be paired with the current number, return true
            if (counts.get(rem) > 1) {
                return true;
            }
        }
    }

    return false;
}

