    }
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if ((arr[i] + arr[j]) % k == 0) {
                return true;
            }
        }
    }
    return false;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize the 0th node as the starting node
  int startNode = 0;

  // Initialize the visited and distance arrays
  boolean[] visited = new boolean[n];
  int[] distance = new int[n];
  Arrays.fill(distance, -1);

  // Set the distance and visited arrays for the 0th node
  distance[startNode] = 0;
  visited[startNode] = true;

  // Create a queue for the BFS
  Queue<Integer> queue = new LinkedList<>();
  queue.add(startNode);

  // Loop through the queue until it is empty
  while (!queue.isEmpty()) {
    // Get the size of the queue
    int queueSize = queue.size();

    // Loop through the queue
    for (int i = 0; i < queueSize; i++) {
      // Get the current node
      int currNode = queue.poll();

      // Loop through the neighbors of the current node
      for (int neighbor : edges[currNode]) {
        // If the neighbor has not been visited and it has an apple
        if (!visited[neighbor] && hasApple[neighbor]) {
          // Set the distance and visited arrays for the neighbor
          distance[neighbor] = distance[currNode] + 1;
          visited[neighbor] = true;

          // Add the neighbor to the queue
          queue.add(neighbor);
        }
      }
    }
  }

  // Return the minimum distance to collect all the apples
  return distance[startNode];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the graph
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = Integer.MAX_VALUE;
    }
    dist[0] = 0;

    // DFS to find the minimum time to collect all apples
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int curNode = queue.poll();
        for (int neighbor : edges[curNode]) {
            if (hasApple[neighbor]) {
                dist[neighbor] = Math.min(dist[neighbor], dist[curNode] + 1);
            }
            if (dist[neighbor] != Integer.MAX_VALUE) {
                queue.offer(neighbor);
            }
        }
    }

    // Find the minimum time
    int minTime = Integer.MAX_VALUE;
    for (int d : dist) {
        minTime = Math.min(minTime, d);
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] distance = new int[n];
  for (int i = 0; i < n; i++) {
    distance[i] = -1;
  }
  distance[0] = 0;

  for (int i = 0; i < n; i++) {
    for (int[] edge : edges) {
      if (hasApple[edge[1]]) {
        distance[edge[0]] = Math.min(distance[edge[0]], distance[edge[1]] + 1);
      }
    }
  }

  int minTime = 0;
  for (int i = 0; i < n; i++) {
    if (distance[i] != -1) {
      minTime = Math.max(minTime, distance[i]);
    }
  }

  return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  // Initialize distance and visited arrays
  int[] distance = new int[n];
  boolean[] visited = new boolean[n];

  // Breadth-first search to find the shortest path to all apples
  Queue<Integer> queue = new LinkedList<>();
  queue.add(0);
  visited[0] = true;
  distance[0] = 0;
  while (!queue.isEmpty()) {
    int current = queue.remove();
    for (int i = 0; i < n; i++) {
      if (edges[current][i] != 0 && !visited[i]) {
        visited[i] = true;
        distance[i] = distance[current] + 1;
        queue.add(i);
      }
    }
  }

  // Sum up the minimum time to reach all apples
  int time = 0;
  for (int i = 0; i < n; i++) {
    if (hasApple[i]) {
      time += distance[i];
    }
  }

  return time;
}

public String sortString(String s) {
    List<Character> chars = new ArrayList<>();
    for (Character c : s.toCharArray()) {
        chars.add(c);
    }
