public String sortString(String s) {
  String result = "";
  int i = 0;
  while (i < s.length()) {
    int min = Integer.MAX_VALUE;
    int max = Integer.MIN_VALUE;
    for (int j = i; j < s.length(); j++) {
      if (s.charAt(j) <= min) {
        min = s.charAt(j);
      }
      if (s.charAt(j) >= max) {
        max = s.charAt(j);
      }
    }
    result += min;
    i = s.indexOf(min) + 1;
    result += max;
    i = s.indexOf(max) + 1;
  }
  return result;
}

public String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < arr.length; i++) {
        char c = arr[i];
        if (i > 0 && arr[i] != arr[i - 1]) {
            result.append(c);
        }
    }
    for (int i = arr.length - 1; i >= 0; i--) {
        char c = arr[i];
        if (i < arr.length - 1 && arr[i] != arr[i + 1]) {
            result.append(c);
        }
    }
    return result.toString();
}

public String sortString(String s) {
    // Sort the string using a combination of selection sort and insertion sort algorithms
    char[] sortedChars = new char[s.length()];
    for (int i = 0; i < s.length(); i++) {
        int smallest = i;
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) < s.charAt(smallest)) {
                smallest = j;
            }
        }
        sortedChars[i] = s.charAt(smallest);
        s = s.substring(0, smallest) + s.substring(smallest + 1);
    }

    for (int i = 0; i < s.length(); i++) {
        int largest = i;
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) > s.charAt(largest)) {
                largest = j;
            }
        }
        sortedChars[i] = s.charAt(largest);
        s = s.substring(0, largest) + s.substring(largest + 1);
    }

    return new String(sortedChars);
}

public String sortString(String s) {
    int[] charCount = new int[256];
    for (char c : s.toCharArray()) {
        charCount[c]++;
    }

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        // smallest character
        char smallest = '_';
        for (char c = 0; c < 256; c++) {
            if (charCount[c] > 0 && (smallest == '_' || c < smallest)) {
                smallest = c;
            }
        }
        result.append(smallest);
        charCount[smallest]--;

        // largest character
        char largest = '_';
        for (char c = 255; c >= 0; c--) {
            if (charCount[c] > 0 && (largest == '_' || c > largest)) {
                largest = c;
            }
        }
        result.append(largest);
        charCount[largest]--;
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the input array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;

    // Check if there exists an element in the array that is equal to the average
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == average) {
            // Split the array into two parts around the element
            int[] left = Arrays.copyOfRange(nums, 0, i);
            int[] right = Arrays.copyOfRange(nums, i + 1, nums.length);

            // Check if the average of the two parts is also equal to the average
            int leftSum = 0;
            for (int num : left) {
                leftSum += num;
            }
            int rightSum = 0;
            for (int num : right) {
                rightSum += num;
            }
            if (leftSum == average && rightSum == average) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the average of the array
    int avg = Arrays.stream(nums).sum() / nums.length;

    // Check if any element is equal to the average
    for (int num : nums) {
        if (num == avg) {
            return true;
        }
    }

    // If no element is equal to the average, check if there are any elements
    // that are greater than or equal to the average and any elements that
    // are less than or equal to the average
    int countGreaterThanOrEqualToAvg = 0;
    int countLessThanOrEqualToAvg = 0;
    for (int num : nums) {
        if (num >= avg) {
            countGreaterThanOrEqualToAvg++;
        } else {
            countLessThanOrEqualToAvg++;
        }
    }

    // Check if there are an equal number of elements greater than or equal to
    // the average and less than or equal to the average
    return countGreaterThanOrEqualToAvg == countLessThanOrEqualToAvg;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the array
    int sum = Arrays.stream(nums).sum();

    // Calculate the average of the array
    double average = sum / (double) nums.length;

    // Create a set to store the unique elements of the array
    Set<Integer> uniqueElements = new HashSet<>();
    for (int num : nums) {
        uniqueElements.add(num);
    }

    // Check if there are two elements with the same average value
    for (int i = 0; i < nums.length - 1; i++) {
        int element1 = nums[i];
        for (int j = i + 1; j < nums.length; j++) {
            int element2 = nums[j];
            if (element1 == element2) {
                continue;
            }
            if (element1 / (double) element2 == average) {
                return true;
            }
        }
    }

    return false;
}

