public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int avg = sum / nums.length;

    int leftSum = 0;
    for (int i = 0; i < nums.length; i++) {
        leftSum += nums[i];
        if (leftSum == avg) {
            return true;
        }
    }

    int rightSum = sum - leftSum;
    for (int i = nums.length - 1; i >= 0; i--) {
        rightSum -= nums[i];
        if (rightSum == avg) {
            return true;
        }
    }

    return false;
}

