public int kthFactor(int n, int k) {
    // Create an array to store the factors of n
    int[] factors = new int[n];

    // Initialize the index of the current factor
    int currentFactorIndex = 0;

    // Loop through all possible factors of n
    for (int i = 1; i <= n; i++) {
        // Check if i is a factor of n
        if (n % i == 0) {
            // If i is a factor of n, add it to the array of factors
            factors[currentFactorIndex++] = i;
        }
    }

    // Check if there are at least k factors
    if (currentFactorIndex < k) {
        // If there are not at least k factors, return -1
        return -1;
    }

    // Return the kth factor
    return factors[k - 1];
}

