public static int squarePermutations(int[] A) {
    // Calculate the sum of each pair of adjacent elements
    int[][] sums = new int[A.length - 1][2];
    for (int i = 0; i < A.length - 1; i++) {
        sums[i][0] = A[i] + A[i + 1];
        sums[i][1] = A[i + 1] + A[i];
    }
    // Check if the sums are perfect squares
    Set<Integer> squares = new HashSet<>();
    for (int[] sum : sums) {
        for (int i = 0; i < sum.length; i++) {
            int x = (int) Math.sqrt(sum[i]);
            if (x * x == sum[i]) {
                squares.add(x);
                break;
            }
        }
    }
    // Count the number of permutations with the same squares
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (squares.contains(A[i])) {
            count++;
        }
    }
    return count;
}

