      while (j < n && heights[j] >= heights[i]) j = right[j];
      right[i] = j;
    }

    int area = 0;
    for (int i = 0; i < n; i++) {
      area = Math.max(area, heights[i] * (right[i] - left[i] - 1));
    }

    return area;
  }

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    for (int i = 0; i < n; i++) {
        left[i] = i;
        for (int j = i - 1; j >= 0; j--) {
            if (heights[j] >= heights[i]) {
                left[i] = j;
                break;
            }
        }
    }

    for (int i = n - 1; i >= 0; i--) {
        right[i] = i;
        for (int j = i + 1; j < n; j++) {
            if (heights[j] >= heights[i]) {
                right[i] = j;
                break;
            }
        }
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i]) * heights[i]);
    }

    return maxArea;
}

