public static int findSmallestInteger(int n) {
    // Step 1: Convert the input number to a string
    String inputStr = Integer.toString(n);

    // Step 2: Sort the characters of the string in ascending order
    char[] sortedChars = inputStr.toCharArray();
    Arrays.sort(sortedChars);

    // Step 3: Reconstruct the sorted string as an integer
    String smallestStr = new String(sortedChars);

    // Step 4: Check if the reconstructed integer is greater than the original number
    int smallestInt = Integer.parseInt(smallestStr);
    if (smallestInt > n) {
        return smallestInt;
    }

    // If none of the steps above produce a valid answer, return -1
    return -1;
}

