public static boolean isBoomerang(int[][] points) {

    // Compute the length of each side of the triangle
    int side1 = Math.hypot(points[1][0] - points[0][0], points[1][1] - points[0][1]);
    int side2 = Math.hypot(points[2][0] - points[1][0], points[2][1] - points[1][1]);
    int side3 = Math.hypot(points[1][0] - points[2][0], points[1][1] - points[2][1]);

    // Compute the dot product of the vectors
    int dot = (points[1][0] - points[0][0]) * (points[2][0] - points[0][0]) + (points[1][1] - points[0][1]) * (points[2][1] - points[0][1]);

    // Check if the dot product of the vectors is zero
    return dot == 0;
}

public static boolean isBoomerang(int[][] points) {
