    if (points[0][1] == points[1][1] && points[0][1] == points[2][1]) {
        return false;
    }

    // Check if the three points are in a counterclockwise order
    if ((points[1][0] - points[0][0]) * (points[2][1] - points[0][1])
            > (points[2][0] - points[0][0]) * (points[1][1] - points[0][1])) {
