    dp[1] = 1;
    int i2 = 1, i3 = 1, i5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[i2] * 2, Math.min(dp[i3] * 3, dp[i5] * 5));
        if (min == dp[i2] * 2) i2++;
        if (min == dp[i3] * 3) i3++;
        if (min == dp[i5] * 5) i5++;
        dp[i] = min;
    }
    return dp[n];
}

